import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./SpendingPriority.css";

function SpendingPriority() {
  const navigate = useNavigate();

  const [priorities, setPriorities] = useState({
    "Food & Groceries": 3,
    Shopping: 3,
    Bills: 4,
    Health: 1,
    Entertainment: 1,
    Transport: 1
  });

  const handleChange = (category, value) => {
    setPriorities({
      ...priorities,
      [category]: Number(value)
    });
  };

  const handleContinue = () => {
    navigate("/budget");
  };

  return (
    <div className="questionnaire-container">
      <div className="questionnaire-card">

        <h2 className="questionnaire-title">
          Set Your Spending Priorities
        </h2>

        {Object.keys(priorities).map((category) => (
          <div className="form-group" key={category}>
            <label className="form-label">{category}</label>

            <select
              className="form-select"
              value={priorities[category]}
              onChange={(e) =>
                handleChange(category, e.target.value)
              }
            >
              <option value={1}>Low Priority</option>
              <option value={2}>Below Average</option>
              <option value={3}>Medium</option>
              <option value={4}>High Priority</option>
              <option value={5}>Essential</option>
            </select>
          </div>
        ))}

        <button className="next-button" onClick={handleContinue}>
          Continue
        </button>

      </div>
    </div>
  );
}

export default SpendingPriority;
